  binary: { data: await this.helpers.prepareBinaryData(buf, 'outrovoice.mp3', 'audio/mpeg') } }];

// Use the bed-mixed outro when the mix produced one; otherwise the dry voice.
let out = null;
try {
  const m = $('Load the outro mix').first();
  if (m && m.binary && m.binary.data) out = { json: { mixed: true }, binary: m.binary };
} catch (e) {}
if (!out) out = { json: { mixed: false }, binary: $('Unpack the outro voice').first().binary };
return [out];

const sd = $getWorkflowStaticData('global');
sd.scripts = sd.scripts || [];
const c = $('Clean the outro').first().json;
sd.scripts.push({ at: new Date().toISOString(), kind: 'outro', words: c.words, opening: c.opening, script: c.script });
if (sd.scripts.length > 60) sd.scripts = sd.scripts.slice(-60);
return [{ json: { saved: true, kind: 'outro', words: c.words } }];

// Decode the with-timestamps response: audio + exact speech boundaries.
const r = $input.first().json;
if (!r || !r.audio_base64) throw new Error('No audio came back from ElevenLabs');
const buf = Buffer.from(r.audio_base64, 'base64');
const a = r.alignment || {};
const ch = a.characters || [];
const st = a.character_start_times_seconds || [];
const en = a.character_end_times_seconds || [];
let speechStart = 0, speechEnd = 0;
for (let i = 0; i < ch.length; i++) { if (String(ch[i]).trim()) { speechStart = st[i] || 0; break; } }
for (let i = ch.length - 1; i >= 0; i--) { if (String(ch[i]).trim()) { speechEnd = en[i] || 0; break; } }
if (!speechEnd) speechEnd = en.length ? en[en.length - 1] : 30;
return [{ json: { speechStart: Math.round(speechStart * 100) / 100, speechEnd: Math.round(speechEnd * 100) / 100 },
  binary: { data: await this.helpers.prepareBinaryData(buf, 'qsvoice.mp3', 'audio/mpeg') } }];

// Pick a random short bed from the Quiet Storm DJ Bed Music folder.
let beds = [];
try {
  beds = $input.all().map((i) => i.json).filter((j) => j && j.name && /\.(mp3|m4a|wav)$/i.test(j.name) && j.type !== 'folder' && j['.tag'] !== 'folder');
} catch (e) {}
const pick = beds.length ? beds[Math.floor(Math.random() * beds.length)] : null;
return [{ json: { doMix: !!pick, bedPath: pick ? (pick.path_display || pick.path_lower || ('/Charles Helstein/Quite Storm Show/DJ Bed Music/' + pick.name)) : '', bedName: pick ? pick.name : null } }];

// Use the bed-mixed break when the mix produced one; otherwise the dry voice.
let mixedFlag = false;
try { mixedFlag = String($('Mix the break').first().json.stdout || '').includes('MIXED'); } catch (e) {}
let out = null;
try {
  const m = $('Load the break mix').first();
  if (m && m.binary && m.binary.data) out = { json: { mixed: mixedFlag, bed: $('Pick a QS bed').first().json.bedName }, binary: m.binary };
} catch (e) {}
if (!out) out = { json: { mixed: false }, binary: $('Unpack the break voice').first().binary };
return [out];
